"""Strict TOML configuration; filesystem paths are relative to the config file."""

from dataclasses import dataclass, field
import math
from pathlib import Path
import tomllib

from virvision.kcs.model import DETAIL_LEVELS, OUTPUT_LANGUAGES
from virvision.kcs.spatial import SpatialProfile
from virvision.vir.query_filter import ConfidenceThresholds
from virvision.vir.token_budget import ScoreWeights


def _unit(value, name: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{name} must be numeric")
    value = float(value)
    if not math.isfinite(value) or not 0 <= value <= 1:
        raise ValueError(f"{name} must be finite and within [0,1]")
    return value


def _device(value: str, name: str) -> str:
    if value not in {"auto", "cpu", "cuda"}:
        raise ValueError(f"{name} must be auto, cpu or cuda")
    return value


@dataclass(frozen=True)
class DetectorConfig:
    provider: str = "ultralytics"
    model: str = "yolo11n.pt"
    confidence: float = 0.25
    iou: float = 0.45
    device: str = "auto"
    max_objects: int = 100
    image_size: int = 640

    def __post_init__(self) -> None:
        if self.provider != "ultralytics":
            raise ValueError("Only the ultralytics detector provider is implemented in Phase 2")
        if not isinstance(self.model, str) or not self.model.strip():
            raise ValueError("perception.detector.model must be a nonempty string")
        object.__setattr__(self, "confidence", _unit(self.confidence, "detector confidence"))
        object.__setattr__(self, "iou", _unit(self.iou, "detector iou"))
        object.__setattr__(self, "device", _device(self.device, "detector device"))
        for name in ("max_objects", "image_size"):
            value = getattr(self, name)
            if isinstance(value, bool) or not isinstance(value, int) or value < 1:
                raise ValueError(f"perception.detector.{name} must be a positive integer")


@dataclass(frozen=True)
class OCRConfig:
    provider: str = "easyocr"
    languages: tuple[str, ...] = ("tr", "en")
    confidence: float = 0.0
    device: str = "auto"
    model_storage_directory: str | None = None
    download_enabled: bool = True
    detector_network: str = "craft"
    dedup_iou: float = 0.80

    def __post_init__(self) -> None:
        if self.provider != "easyocr":
            raise ValueError("Only the easyocr OCR provider is implemented in Phase 2")
        if not isinstance(self.languages, (tuple, list)) or not self.languages:
            raise ValueError("perception.ocr.languages must be a nonempty list")
        languages = tuple(self.languages)
        if any(not isinstance(item, str) or not item.strip() for item in languages):
            raise ValueError("perception.ocr.languages must contain nonempty strings")
        object.__setattr__(self, "languages", languages)
        object.__setattr__(self, "confidence", _unit(self.confidence, "OCR confidence"))
        object.__setattr__(self, "dedup_iou", _unit(self.dedup_iou, "OCR dedup_iou"))
        object.__setattr__(self, "device", _device(self.device, "OCR device"))
        if self.model_storage_directory is not None and (
            not isinstance(self.model_storage_directory, str) or not self.model_storage_directory
        ):
            raise ValueError("OCR model_storage_directory must be a path or null")
        if not isinstance(self.download_enabled, bool):
            raise ValueError("OCR download_enabled must be boolean")
        if self.detector_network not in {"craft", "dbnet18"}:
            raise ValueError("OCR detector_network must be craft or dbnet18")


@dataclass(frozen=True)
class PerceptionConfig:
    detector: DetectorConfig = field(default_factory=DetectorConfig)
    ocr: OCRConfig = field(default_factory=OCRConfig)
    warmup_runs: int = 0

    def __post_init__(self) -> None:
        if (
            isinstance(self.warmup_runs, bool)
            or not isinstance(self.warmup_runs, int)
            or self.warmup_runs < 0
        ):
            raise ValueError("perception.warmup_runs must be a nonnegative integer")

    def to_dict(self) -> dict:
        return {
            "detector": vars(self.detector).copy(),
            "ocr": {**vars(self.ocr), "languages": list(self.ocr.languages)},
            "warmup_runs": self.warmup_runs,
        }


@dataclass(frozen=True)
class LensConfig:
    language: str = "tr"
    detail: str = "balanced"

    def __post_init__(self) -> None:
        if self.language not in OUTPUT_LANGUAGES:
            raise ValueError("lens.language must be tr or en")
        if self.detail not in DETAIL_LEVELS:
            raise ValueError("lens.detail must be compact, balanced or detailed")


@dataclass(frozen=True)
class Config:
    tokenizer_path: str | None = None
    budget: int = 256
    weights: ScoreWeights = field(default_factory=ScoreWeights)
    confidence: ConfidenceThresholds = field(default_factory=ConfidenceThresholds)
    seed: int = 0
    perception: PerceptionConfig = field(default_factory=PerceptionConfig)
    lens: LensConfig = field(default_factory=LensConfig)
    spatial: SpatialProfile = field(default_factory=SpatialProfile)


def _strict_section(data: dict, allowed: set[str], name: str) -> dict:
    if not isinstance(data, dict):
        raise ValueError(f"{name} must be a TOML table")
    unknown = data.keys() - allowed
    if unknown:
        raise ValueError(f"Unknown config options in {name}: {', '.join(sorted(unknown))}")
    return data


def _resolve(value: str | None, base: Path) -> str | None:
    if value is None:
        return None
    path = Path(value)
    if path.is_absolute() or path.parent != Path("."):
        return str((base / path).resolve()) if not path.is_absolute() else str(path.resolve())
    return value


def load_config(path: Path | None = None) -> Config:
    if path is None:
        return Config()
    path = path.resolve()
    with path.open("rb") as handle:
        data = tomllib.load(handle)
    allowed = {
        "tokenizer": {"path"},
        "budget": {"tokens"},
        "weights": set(vars(ScoreWeights())),
        "confidence": set(vars(ConfidenceThresholds())),
        "reproducibility": {"seed"},
        "perception": {"warmup_runs", "detector", "ocr"},
        "lens": set(vars(LensConfig())),
        "spatial": set(vars(SpatialProfile())),
    }
    for section, values in data.items():
        if section not in allowed:
            raise ValueError(f"Unknown config section: {section}")
        _strict_section(values, allowed[section], section)

    spec = data.get("tokenizer", {}).get("path")
    if spec is not None and (not isinstance(spec, str) or not spec):
        raise ValueError("tokenizer.path must be a nonempty string")
    if spec != "mock":
        spec = _resolve(spec, path.parent)
    budget = data.get("budget", {}).get("tokens", 256)
    seed = data.get("reproducibility", {}).get("seed", 0)
    if isinstance(budget, bool) or not isinstance(budget, int) or budget < 1:
        raise ValueError("budget.tokens must be a positive integer")
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise ValueError("reproducibility.seed must be an integer")

    perception_data = data.get("perception", {})
    detector_data = _strict_section(
        perception_data.get("detector", {}), set(vars(DetectorConfig())), "perception.detector"
    ).copy()
    ocr_data = _strict_section(
        perception_data.get("ocr", {}), set(vars(OCRConfig())), "perception.ocr"
    ).copy()
    if "model" in detector_data:
        detector_data["model"] = _resolve(detector_data["model"], path.parent)
    if "model_storage_directory" in ocr_data:
        ocr_data["model_storage_directory"] = _resolve(
            ocr_data["model_storage_directory"], path.parent
        )
    perception = PerceptionConfig(
        DetectorConfig(**detector_data),
        OCRConfig(**ocr_data),
        perception_data.get("warmup_runs", 0),
    )
    return Config(
        tokenizer_path=spec,
        budget=budget,
        weights=ScoreWeights(**data.get("weights", {})),
        confidence=ConfidenceThresholds(**data.get("confidence", {})),
        seed=seed,
        perception=perception,
        lens=LensConfig(**data.get("lens", {})),
        spatial=SpatialProfile(**data.get("spatial", {})),
    )
